// publicPaths are answered before authentication, so the projection parameter
// requireAuth adds to every other GET does not reach them.
var publicPaths = map[string]bool{
	"/system/version":     true,
	"/auth/status":        true,
	"/auth/login":         true,
	"/auth/oidc/start":    true,
	"/auth/oidc/callback": true,
		return false
	}
	return true
}

// ClientIP is the address a request arrived from, canonicalised so that it is
// both a stable key and a value PostgreSQL accepts for an `inet` column.
//
// Every caller that stores it binds it into an `::inet` cast that maps only the
// empty string to NULL, and an address the cast refuses does not lose one
// column — it fails the whole statement. That drops the audit event,
// LOGIN_FAILED included, and in auth.Login it fails the session insert, so the
// client cannot log in at all.
// RemoteAddr carries the zone of a link-local address (`[fe80::1%eth0]:52000`),
// which `inet` rejects, so the zone is dropped here; an address that is not an
// address at all (a Unix socket peer is "@") becomes "" and is stored as NULL
// instead of taking its row down with it. An IPv4-mapped form is unmapped so
// one client keys and reads the same way on a dual-stack listener.
func ClientIP(r *http.Request) string {
	raw := r.RemoteAddr
	if host, _, err := net.SplitHostPort(raw); err == nil {
		raw = host
	}
	addr, err := netip.ParseAddr(raw)
	if err != nil {
		return ""
	}
	return addr.WithZone("").Unmap().String()
}

func Bearer(r *http.Request) string {
	v := strings.TrimSpace(r.Header.Get("Authorization"))
	if len(v) < 8 || !strings.EqualFold(v[:7], "Bearer ") {
		return ""
	}
	return strings.TrimSpace(v[7:])
}

// IntQuery reads a bounded integer from the query string. A key that is absent,
// is not a decimal integer, or lands outside [min, max] yields fallback.
//
// The parse is strict on purpose. fmt.Sscan stops at the first byte it cannot
// use and reports no error about the rest, so it read "1e3" as 1, "0x10" as 16
// and "50abc" as 50: a caller was answered with a different number than it sent,
// under a schema this server publishes as `type: integer` with a minimum and a
// maximum. Surrounding spaces are still accepted because a query string carries
// a "+" as a space.
func IntQuery(r *http.Request, key string, fallback, min, max int) int {
	n, ok := intQuery(r, key)
	if !ok || n < min || n > max {
		return fallback
	}
	return n
}

// ClampQuery is IntQuery for a filter whose fallback switches the filter off.
// Falling back there answers a request to narrow with everything the caller did
// not ask for, so an out-of-range value is pulled to the nearest bound instead
// and only an unreadable one yields fallback.
func ClampQuery(r *http.Request, key string, fallback, min, max int) int {
	n, ok := intQuery(r, key)
	msg := err.Error()
	status := http.StatusBadRequest
	code := "invalid_request"
	sqlstate := ""
	var pgErr *pgconn.PgError
	isPg := errors.As(err, &pgErr) || strings.Contains(msg, "SQLSTATE")
	switch {
	case errors.Is(err, pgx.ErrNoRows) || msg == "no rows in result set":
		status = 404
		code = "not_found"
		// The driver's phrasing reached API and MCP clients verbatim.
		msg = "요청한 데이터를 찾을 수 없거나 접근 권한이 없습니다."
	case isPg:
		// A PostgreSQL error before the English substrings below, because they
		// read the driver's own sentence: "permission denied for table contacts"
		// left as a 403 carrying the table name, and "relation ... does not
		// exist" left as a 400 for what is a server defect. The same table is
		// in internal/mcp/results.go sanitizeToolError, which is how the MCP
		// path reads the same error; keep the two in step.
		if pgErr != nil {
			sqlstate = pgErr.Code
		}
		status, code, msg = pgErrorVerdict(sqlstate)
	case database.Unreachable(err):
		// PostgreSQL was never reached, so there is no SQLSTATE for the table
		// above to read and the default 400 used to hand the client the driver's
		// own sentence — which carries the database role, the database name and
		// the internal host:port. A database that went away is a server fault,
		// and the 5xx also keeps the idempotency cache from storing the answer.
		// This sits after isPg on purpose: a refused authentication wraps a
		// PgError (28P01) in a ConnectError, and that one should still log its
		// sqlstate. Both end as a 500. msg is left alone — the status >= 500
		// block below logs the original and replaces the sentence.
		status = http.StatusInternalServerError
		code = "internal_error"
	case database.Interrupted(err):
		// The query was cut short instead of answered — today almost always a
		// caller that went away, which makes net/http cancel r.Context(). There
		// is no SQLSTATE and no ConnectError, so this fell through to the default
		// 400 and told the client, the logs and the metrics that the input was
		// wrong while handing back the driver's "context canceled". This sits
		// after database.Unreachable on purpose: a dial that timed out wraps
		// context.DeadlineExceeded inside a *pgconn.ConnectError, and that one
		// must keep the verdict above so its sqlstate still reaches the log.
		// msg is left alone — the status >= 500 block below replaces it.
		status = http.StatusInternalServerError
		code = "internal_error"
	case strings.Contains(msg, "not found"):
		status = 404
		code = "not_found"
	case strings.Contains(msg, "permission") || strings.Contains(msg, "access denied") || strings.Contains(msg, "designated approver"):
		status = 403
		code = "forbidden"
	case strings.Contains(msg, "another user") || strings.Contains(msg, "already") || strings.Contains(msg, "pending"):
		status = 409
		code = "conflict"
	}
	if status >= 500 {
		s.Log.Error("service error", "error", err, "sqlstate", sqlstate, "requestId", httpx.RequestID(r.Context()))
		msg = "서버 오류가 발생했습니다."
	}
	httpx.ErrorJSON(w, r, status, code, msg, nil)
}

// pgErrorVerdict maps a SQLSTATE to the status, code and sentence a REST client
// receives. The sentences are the ones internal/mcp/results.go sanitizeToolError
// gives an MCP client for the same code, so one database error does not become
// two different answers depending on which door the caller came through. The
// two functions stay separate on purpose: MCP returns a string, REST returns a
// verdict, and internal/server already imports internal/mcp. An unrecognised
// code — including a missing one — is a server defect, not the caller's fault;
// serviceError logs the original and answers with the generic sentence.
// sqlstate_parity_test.go compares the two tables and fails when they drift.
func pgErrorVerdict(sqlstate string) (int, string, string) {
	switch sqlstate {
	case "22P02":
		return http.StatusBadRequest, "invalid_request", "입력 값의 형식이 올바르지 않습니다. ID는 목록·검색 도구가 돌려준 UUID를 그대로 사용하세요."
	case "22007", "22008":
		return http.StatusBadRequest, "invalid_request", "날짜 형식이 올바르지 않습니다. YYYY-MM-DD 형식을 사용하세요."
	case "22003":
		return http.StatusBadRequest, "invalid_request", "숫자가 허용 범위를 벗어났습니다."
	case "23502", "23514":
		return http.StatusBadRequest, "invalid_request", "필수 값이 비었거나 허용되지 않는 값입니다."
	case "23505":
		return http.StatusConflict, "conflict", "같은 값이 이미 등록되어 있습니다. 기존 데이터를 조회해 수정하세요."
	case "23503":
		return http.StatusConflict, "conflict", "연결 대상이 없거나 다른 데이터가 참조하고 있어 처리할 수 없습니다."
	case "40001", "40P01":
		return http.StatusConflict, "conflict", "동시에 처리된 다른 요청과 충돌했습니다. 잠시 후 다시 시도하세요."
	}
	return http.StatusInternalServerError, "internal_error", ""
}
